    console.log(`  shelter tries: ${sl.tries} - ringed ${sl.ringed} / laneLost ${sl.laneLost} / died ${sl.died} / open ${sl.open} - book ${book}/${sl.tries}; pregate refusals ${sl.pregate}`)
